mapper.select:
SELECT 
	MAX(tracking_response_id)  tracking_response_id

    ,MIN(receive_val + 0) totalReceiveVal


    ,MAX(receive_val + 0) totalReceiveVal


    ,avg(receive_val) totalReceiveVal


    ,sum(receive_val) totalReceiveVal


    ,std(receive_val) totalReceiveVal

FROM
    tracking_response_record
WHERE 1=1


	 and tracking_response_id >= #{detectRecordStartId} and tracking_response_id <= #{detectRecordEndId}





	 and tracking_response_id >= #{resRecordId}



	 and tracking_process_id = #{trackingProcessId}


	 and request_tracking_id = #{requestTrackingId}


	order by tracking_response_id desc


	limit 0, #{bufferSize}

SELECT


		MIN(receive_val + 0) totalReceiveVal


		MAX(receive_val + 0) totalReceiveVal


		avg(receive_val) totalReceiveVal


		sum(receive_val) totalReceiveVal


		std(receive_val) totalReceiveVal


		NULL totalReceiveVal


FROM
(
 	SELECT receive_val
 	FROM tracking_response_record
 	WHERE 1=1


		 and tracking_response_id >= #{detectRecordStartId} and tracking_response_id <= #{detectRecordEndId}




		 and tracking_response_id >= #{resRecordId}



		 and tracking_process_id = #{trackingProcessId}


		 and request_tracking_id = #{requestTrackingId}


		order by tracking_response_id desc


		limit 0, #{bufferSize}

) A

