				result_value
			)
				VALUES
			(				
				#{trackingProcessIdentifier},
				#{resultValue}
		   )
		   ON DUPLICATE KEY UPDATE 
           result_value = #{resultValue}

mapper.update:
  		UPDATE tracking_response_data
			SET
			tracking_process_identifier = #{trackingProcessIdentifier},
			result_value = #{resultValue}
			WHERE 
				tracking_process_identifier = #{trackingProcessIdentifier}

